package com.ruoyi.system.service.impl;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.shop.MallInventoryAdjust; import com.ruoyi.system.domain.shop.MallProductSku; import com.ruoyi.system.mapper.shop.MallOrderMapper; import com.ruoyi.system.service.IMallInventoryService;
@Service public class MallInventoryServiceImpl implements IMallInventoryService { @Autowired private MallOrderMapper mapper; @Transactional(rollbackFor=Exception.class) public int adjust(MallInventoryAdjust a,String operator){if(a.getSkuId()==null||a.getQuantity()==null||a.getQuantity()<=0||a.getReason()==null||a.getReason().trim().isEmpty()||(!"INBOUND".equals(a.getBizType())&&!"ADJUST".equals(a.getBizType())))throw new ServiceException("库存调整参数非法");MallProductSku sku=mapper.selectSkuStockForUpdate(a.getSkuId());if(sku==null)throw new ServiceException("SKU不存在");if(mapper.increaseSkuStock(a.getSkuId(),a.getQuantity())==0)throw new ServiceException("库存调整失败");mapper.insertInventoryAdjustLog(a.getSkuId(),a.getBizType(),a.getReason(),sku.getAvailableStock(),sku.getAvailableStock()+a.getQuantity(),sku.getLockedStock(),operator);return 1;} }
